import pandas as pd
import numpy as np

def model(regime, n, seed):
    np.random.seed(seed)
    line = int(regime.config.get('line', regime.config.get('campaign_line', 1)))
    driver = float(regime.config.get('driver', 0.0))
    # parameters estimated from full data
    intercepts = {1: 18.648, 2: 18.920, 3: 19.039, 4: 18.952, 5: 18.701}
    common_slope = 0.097
    resid_stds = {1: 2.631, 2: 2.048, 3: 2.231, 4: 2.262, 5: 2.341}
    mean = intercepts[line] + common_slope * driver
    outcome = np.random.normal(loc=mean, scale=resid_stds[line], size=n)
    return pd.DataFrame({'outcome': outcome})

